let raw = $input.first().json;
let data;
try { data = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(e) { data = raw; }
if (data.body && typeof data.body === 'object') data = data.body;
if (data.payload && typeof data.payload === 'object') data = data.payload;

const now = new Date().toISOString();
const asunto = data.asunto || data.subject || data.title || 'Sin asunto';
const remitente = data.emailOrigen || data.from || data.sender || '';
const texto = data.texto || data.text || data.body_plain || data.body_text || JSON.stringify(data);

return [{
  json: {
    fecha: now,
    fecha_origen: data.fechaRecepcion || data.date || now,
    fuente: data.fuenteOrigen || 'gmail',
    email_origen: remitente,
    email_dest: data.emailDestinatario || data.to || 'contacto@teknoconecta.com',
    msg_id: data.idMensajeGmail || data.messageId || data.id || '',
    payload: JSON.stringify(data),
    texto_info: 'Asunto: ' + asunto + ' - Remitente: ' + remitente + ' - ' + texto,
    estado_id: 1,
    intentos: 0
  }
}];
